program='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    markers = [v for v, n in counts.items() if v != background]
    if not markers:
        return out
    marker = max(markers, key=lambda v: counts[v])
    fill = 3
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(positions, positions[1:]):
            for c in range(a + 1, b):
                if out[r][c] == background:
                    out[r][c] = fill
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(positions, positions[1:]):
            for r in range(a + 1, b):
                if out[r][c] == background:
                    out[r][c] = fill
    return out
'''
